#!/usr/bin/env python3
"""Stronger PathBudget feasibility test against locality-aware baselines.

This follow-up checks whether PathBudget is more than "keep TP local".

ASTRA usage:
  * This script reuses the ASTRA logical-topology calibration generated by
    tools/pathbudget_feasibility.py when available.

External model:
  * Depth reach, per-circuit bandwidth, latency, loss, port/radix cost, and
    circuit/wavelength budget.
  * Total optical resource budget is fixed. Each policy gets the same 12 circuit
    units and can only decide how to split them among TP/PP/DP.
"""

from __future__ import annotations

import argparse
import csv
import json
import math
from dataclasses import asdict, dataclass
from pathlib import Path
from statistics import mean
from typing import Iterable


REPO_ROOT = Path(__file__).resolve().parents[1]
AXES = ("TP", "PP", "DP")
TOTAL_RESOURCE_UNITS = 12
INJECTION_CAP_GBPS = 2400.0


@dataclass(frozen=True)
class WorkloadSpec:
    name: str
    params_b: float
    layers: int
    hidden: int
    seq_len: int
    tp: int
    pp: int
    dp: int
    microbatches: int
    microbatch_size: int
    critical_tp: float
    critical_pp: float
    critical_dp: float


@dataclass(frozen=True)
class AxisSignature:
    axis: str
    payload_gb: float
    events: int
    group_size: int
    min_depth: int
    critical_weight: float
    frequency: str


@dataclass(frozen=True)
class DepthSpec:
    depth: int
    reach: int
    bandwidth_per_unit_gbps: float
    latency_us: float
    port_cost_per_unit: float
    loss_db: float
    reconfig_us: float


@dataclass(frozen=True)
class Regime:
    name: str
    description: str
    depths: dict[int, DepthSpec]


@dataclass(frozen=True)
class Budget:
    loss_name: str
    loss_db: float
    port_name: str
    port_units: float


@dataclass(frozen=True)
class Policy:
    name: str
    depths: dict[str, int]
    units: dict[str, int]


@dataclass
class EvalResult:
    workload: str
    regime: str
    loss_budget: str
    port_budget: str
    policy: str
    depth_budget: str
    time_s: float | None
    port_usage: float
    max_loss_db: float
    feasible: bool
    failure_reason: str


@dataclass
class ComparisonRow:
    workload: str
    regime: str
    loss_budget: str
    port_budget: str
    baseline: str
    baseline_depth_budget: str
    pathbudget_depth_budget: str
    baseline_time_s: float | None
    pathbudget_time_s: float | None
    oracle_time_s: float | None
    speedup: float | None
    oracle_gap_pct: float | None
    verdict: str


